import * as React from "react";
import { type VariantProps } from "class-variance-authority";
import { ToggleGroup as ToggleGroupPrimitive } from "radix-ui";

import { cn } from "@/lib/didact/cn";
import { toggleVariants } from "@/components/ui/toggle";

/**
 * ToggleGroup / ToggleGroupItem -- a roving-tabindex group of `Toggle`s (single or multiple
 * selection), adapted from the same reference kit as Button (see button.tsx's header
 * comment). Backed by `radix-ui`'s `ToggleGroup`, which owns the keyboard roving/selection
 * behavior; this layer only supplies the shared `variant`/`size`/`spacing` styling via context, so
 * every `ToggleGroupItem` matches the group's look unless it overrides its own. The group uses
 * fixed borders without a container shadow.
 */

const ToggleGroupContext = React.createContext<
  VariantProps<typeof toggleVariants> & {
    spacing?: number;
  }
>({
  size: "default",
  variant: "default",
  spacing: 0,
});

function ToggleGroup({
  className,
  variant,
  size,
  spacing = 0,
  children,
  ...props
}: React.ComponentProps<typeof ToggleGroupPrimitive.Root> &
  VariantProps<typeof toggleVariants> & {
    spacing?: number;
  }) {
  return (
    <ToggleGroupPrimitive.Root
      data-slot="toggle-group"
      data-variant={variant}
      data-size={size}
      className={cn(
        "group/toggle-group flex w-fit items-center rounded-md",
        className,
      )}
      {...props}
    >
      <ToggleGroupContext.Provider value={{ variant, size, spacing }}>
        {children}
      </ToggleGroupContext.Provider>
    </ToggleGroupPrimitive.Root>
  );
}

function ToggleGroupItem({
  className,
  children,
  variant,
  size,
  ...props
}: React.ComponentProps<typeof ToggleGroupPrimitive.Item> & VariantProps<typeof toggleVariants>) {
  const context = React.useContext(ToggleGroupContext);

  return (
    <ToggleGroupPrimitive.Item
      data-slot="toggle-group-item"
      data-variant={context.variant || variant}
      data-size={context.size || size}
      className={cn(
        toggleVariants({
          variant: context.variant || variant,
          size: context.size || size,
        }),
        "min-w-0 shrink-0 rounded-none px-3 first:rounded-l-md last:rounded-r-md focus:z-10 focus-visible:z-10",
        "data-[variant=outline]:border-l-0 data-[variant=outline]:first:border-l",
        className,
      )}
      {...props}
    >
      {children}
    </ToggleGroupPrimitive.Item>
  );
}

export { ToggleGroup, ToggleGroupItem };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * `cn` -- Didact's class-composition helper (docs/design-principles.md §3), mirrored here from
 * packages/core/src/lib/cn.ts so `@didact/ui` has no dependency on `@didact/core`: `clsx` resolves
 * conditional/array/falsy class inputs, `tailwind-merge` then resolves conflicting Tailwind
 * utilities (e.g. a caller's `className="px-4"` overriding this component's own `px-2`) by keeping
 * the last one instead of leaving both in the DOM. Every Didact component that accepts `className`
 * must merge it LAST through this helper, not a manual array-join, so a single instance can be
 * restyled inline without fighting the base classes.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}
